import unittest
from codec import glob_literal_escape as core

class OrdinaryTests(unittest.TestCase):
    def test_ordinary_0(self):
        self.assertEqual(core.escape_glob("abc"),"abc")

    def test_ordinary_1(self):
        self.assertEqual(core.escape_glob(""),"")

    def test_ordinary_2(self):
        self.assertEqual(core.escape_glob("]"),"]")

    def test_ordinary_3(self):
        self.assertEqual(core.escape_glob("a-b.txt"),"a-b.txt")

    def test_ordinary_4(self):
        self.assertEqual(core.escape_glob("café"),"café")
